@@ -1,12 +1,43 @@
+import { readFileSync, writeFileSync, mkdirSync } from "fs";
+import { join } from "path";
+
 interface Entry {
   value: string;
   expiresAt: number;
 }

-const store = new Map<string, Entry>();
+const dataDir = process.env.SESSION_DATA_DIR || "./session-data";
+const storeFile = join(dataDir, "sessions.json");
+
+const ensureDir = (): void => {
+  try {
+    mkdirSync(dataDir, { recursive: true });
+  } catch {
+    // Directory already exists
+  }
+};
+
+const loadStore = (): Map<string, Entry> => {
+  try {
+    const data = readFileSync(storeFile, "utf-8");
+    const obj = JSON.parse(data);
+    return new Map(Object.entries(obj));
+  } catch {
+    return new Map();
+  }
+};
+
+const saveStore = (store: Map<string, Entry>): void => {
+  ensureDir();
+  const obj = Object.fromEntries(store);
+  writeFileSync(storeFile, JSON.stringify(obj));
+};
+
+let store = loadStore();

 export const put = (key: string, value: string, ttlMs: number): void => {
   store.set(key, { value, expiresAt: Date.now() + ttlMs });
+  saveStore(store);
 };

